import type { ComponentLogger } from '../../utils/component-logger.js';

/**
 * Story 370 (pwa-nutrition-15): Remove on a photo still waiting in the offline queue. The entry
 * shipped anyway and the drain put the removed photo back on its row. Dropping it from the queue is
 * the Remove. Imported lazily, as `files.service` does, so the store loads only when needed.
 */
export async function cancelQueuedUpload(queueId: string, log: ComponentLogger): Promise<void> {
    try {
        const { deleteUpload } = await import('./image-upload-store.js');
        await deleteUpload(queueId);
    } catch (err) {
        log.error('could not cancel the queued photo upload', { queueId, err });
    }
}
